const input = $input.first()?.json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const events = Array.isArray(body.events) ? body.events : [];

if (events.length === 0) {
  return [{ json: { shouldReply: false, reason: 'empty-events' } }];
}

const event = events[0] || {};
const isText = event.type === 'message' && event.message?.type === 'text';
const replyToken = typeof event.replyToken === 'string' ? event.replyToken : '';

if (!isText || !replyToken) {
  return [{ json: { shouldReply: false, reason: 'non-text-or-missing-reply-token' } }];
}

const userText = String(event.message?.text || '').trim();
const sourceUserId = String(event.source?.userId || '');

return [{
  json: {
    shouldReply: true,
    replyToken,
    userText,
    userIdSuffix: sourceUserId ? sourceUserId.slice(-6) : '',
    receivedAt: new Date().toISOString()
  }
}];

const eventData = $('解析 LINE 事件').first().json;
const rows = $input.all()
  .map((item) => ({
    keyword: String(item.json?.['關鍵字'] || '').trim(),
    reply: String(item.json?.['回覆'] || '').trim()
  }))
  .filter((row) => row.keyword && row.reply);

const normalizedText = String(eventData.userText || '').trim();
const normalRows = rows.filter((row) => !['預設', 'default'].includes(row.keyword.toLowerCase()));
const matched = normalRows.find((row) => normalizedText.includes(row.keyword));
const defaultRow = rows.find((row) => ['預設', 'default'].includes(row.keyword.toLowerCase()));
const replyText = matched?.reply || defaultRow?.reply || '我請專人回覆您';

return [{
  json: {
    ...eventData,
    replyText,
    waitingForHuman: false,
    replyBody: {
      replyToken: eventData.replyToken,
      messages: [{ type: 'text', text: replyText }]
    }
  }
}];
